def count_palindromes(lower_limit: int, upper_limit: int) -> int:
    """
    Returns the count of palindromic numbers within the inclusive range from lower_limit to upper_limit.
    """
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    count = 0
    for number in range(lower_limit, upper_limit + 1):
        if is_palindrome(number):
            count += 1
    return count

