class Node:
    def __init__(self, key):
        self.key = key
        self.left = None
        self.right = None
        self.height = 1  # Height of node in tree
        self.balance = 0  # Balance factor
        self.sum = key  # Sum of subtree

class AvlTree:
    def __init__(self):
        self.root = None

    def insert(self, key):
        if not self.root:
            self.root = Node(key)
        else:
            self.root = self._insert(self.root, key)

    def _insert(self, root, key):
        if not root:
            return Node(key)

        if key < root.key:
            root.left = self._insert(root.left, key)
        else:
            root.right = self._insert(root.right, key)

        self.update_heights(root)
        self.update_sums(root)
        self.update_balances(root)

        return self.re_balance(root)

    def re_balance(self, root):
        if root.balance < -1:
            if root.left.balance > 0:
                root.left = self.rotate_left(root.left)
            return self.rotate_right(root)

        if root.balance > 1:
            if root.right.balance < 0:
                root.right = self.rotate_right(root.right)
            return self.rotate_left(root)

        return root

    def update_heights(self, root):
        if root:
            left_height = root.left.height if root.left else 0
            right_height = root.right.height if root.right else 0
            root.height = max(left_height, right_height) + 1

    def update_balances(self, root):
        if root:
            left_height = root.left.height if root.left else 0
            right_height = root.right.height if root.right else 0
            root.balance = right_height - left_height

    def update_sums(self, root):
        if root:
            left_sum = root.left.sum if root.left else 0
            right_sum = root.right.sum if root.right else 0
            root.sum = root.key + left_sum + right_sum

    def rotate_right(self, y):
        x = y.left
        T2 = x.right

        x.right = y
        y.left = T2

        self.update_heights(y)
        self.update_heights(x)
        self.update_balances(y)
        self.update_balances(x)
        self.update_sums(y)
        self.update_sums(x)

        return x

    def rotate_left(self, x):
        y = x.right
        T2 = y.left

        y.left = x
        x.right = T2

        self.update_heights(x)
        self.update_heights(y)
        self.update_balances(x)
        self.update_balances(y)
        self.update_sums(x)
        self.update_sums(y)

        return y

    def range_sum(self, L, R):
        """Calculate the sum of all elements in the tree within the inclusive range [L, R].

        >>> avl = AvlTree()
        >>> avl.insert(10)
        >>> avl.insert(5)
        >>> avl.insert(15)
        >>> avl.insert(3)
        >>> avl.insert(8)
        >>> avl.insert(12)
        >>> avl.insert(18)
        >>> avl.range_sum(5, 15)
        50
        """
        return self._range_sum(self.root, L, R)

    def _range_sum(self, root, L, R):
        if not root:
            return 0

        if root.key < L:
            return self._range_sum(root.right, L, R)
        elif root.key > R:
            return self._range_sum(root.left, L, R)
        else:
            return (root.key + 
                    self._range_sum(root.left, L, R) + 
                    self._range_sum(root.right, L, R))

